<?php
use App\Http\Controllers\{AdminController,AuthController,DashboardController,GigController,HomeController,MessageController,OrderController,PaymentController,ReviewController};
use Illuminate\Support\Facades\Route;
Route::get('/',HomeController::class)->name('home');
Route::get('/gigs', [GigController::class,'index'])->name('gigs.index'); Route::get('/gigs/create',[GigController::class,'create'])->middleware('auth')->name('gigs.create'); Route::post('/gigs',[GigController::class,'store'])->middleware('auth')->name('gigs.store'); Route::get('/gigs/{gig}',[GigController::class,'show'])->name('gigs.show');
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login']);Route::get('/register',[AuthController::class,'showRegister'])->name('register');Route::post('/register',[AuthController::class,'register']);});
Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware('auth')->group(function(){Route::get('/dashboard',DashboardController::class)->name('dashboard');Route::post('/gigs/{gig}/order',[OrderController::class,'store'])->name('orders.store');Route::get('/orders/{order}',[OrderController::class,'show'])->name('orders.show');Route::post('/orders/{order}/deliver',[OrderController::class,'deliver'])->name('orders.deliver');Route::post('/orders/{order}/accept',[OrderController::class,'accept'])->name('orders.accept');Route::post('/orders/{order}/reviews',[ReviewController::class,'store'])->name('reviews.store');Route::post('/gigs/{gig}/message',[MessageController::class,'start'])->name('messages.start');Route::get('/messages/{conversation}',[MessageController::class,'show'])->name('messages.show');Route::post('/messages/{conversation}',[MessageController::class,'send'])->name('messages.send');});
Route::get('/payments/callback',[PaymentController::class,'callback'])->middleware('auth')->name('payments.callback');
Route::middleware(['auth','admin'])->prefix('admin')->name('admin.')->group(function(){Route::get('/',[AdminController::class,'index'])->name('dashboard');Route::post('/gigs/{gig}/approve',[AdminController::class,'approveGig'])->name('gigs.approve');Route::post('/gigs/{gig}/reject',[AdminController::class,'rejectGig'])->name('gigs.reject');});
